script:
export const meta = {
  name: "ssb-brief",
  description: "3-paragraph brief on solid-state batteries",
  phases: [
    { name: "research", title: "Parallel research on commercialization, technology, and market" },
    { name: "synthesis", title: "Synthesize into 3-paragraph brief with sources" }
  ]
};

const research = await parallel(
  agent({
    prompt: `Research the latest commercialization progress for solid-state batteries as of 2024-2025. Key companies (Toyota, QuantumScape, Solid Power, Samsung SDI, CATL, Factorial), announced timelines, pilot/production milestones, and any vehicles or products using solid-state cells. Return 4-6 concise bullet points WITH specific source URLs (news articles, press releases, reputable outlets).`,
    tools: ["ctx_fetch_and_index", "ctx_search"]
  }),
  agent({
    prompt: `Research the core technical advances and remaining challenges in solid-state battery technology as of 2024-2025. Cover: solid electrolyte chemistries (sulfide, oxide, polymer), lithium-metal anode issues (dendrites, interface resistance), manufacturing/scalability hurdles, and recent lab breakthroughs. Return 4-6 concise bullet points WITH specific source URLs (journal summaries, reputable tech/news outlets).`,
    tools: ["ctx_fetch_and_index", "ctx_search"]
  }),
  agent({
    prompt: `Research the market outlook and competitive landscape for solid-state batteries: projected market size, cost trajectory vs. conventional Li-ion, automotive OEM partnerships, and analyst forecasts for mainstream adoption. Return 4-6 concise bullet points WITH specific source URLs (analyst reports, reputable business/energy outlets).`,
    tools: ["ctx_fetch_and_index", "ctx_search"]
  })
);

const brief = await agent({
  prompt: `Synthesize the following research into a 3-paragraph brief on the current state of solid-state batteries. Paragraph 1: commercialization progress & timelines. Paragraph 2: technical advances & remaining challenges. Paragraph 3: market outlook & adoption forecast. Keep it tight, factual, non-hyped. After the three paragraphs, list a "Sources" section with the URLs provided, deduplicated. Research:\n\n${JSON.stringify(research, null, 2)}`
});

return brief;
